def _adjust_start_date(config, data_proxy):
    if config.strategy.run_type == RunType.TRADING:
        if config.strategy.start_date > config.strategy.end_date:
            raise ValueError('参数错误，开始时间{start_date}应大于结束时间{end_date}， 请检查参数设置是否正确'.format(start_date=config.strategy.start_date, end_date=config.strategy.end_date))
        now_date = datetime.datetime.now().date()
        start_date = convert_int_to_date(config.strategy.start_date)
        end_date = convert_int_to_date(config.strategy.end_date)
        if now_date > end_date:
            end_date = now_date
        config.strategy.start_date = start_date
        config.strategy.end_date = end_date
        return None
    else:
        origin_start_date, origin_end_date = (config.strategy.start_date, config.strategy.end_date)
        if len(data_proxy.get_trading_dates(origin_start_date, origin_end_date)) == 0:
            raise ValueError(_(f'日期区间{origin_start_date!s}-{origin_end_date!s}没有交易日. 请检查交易区间'))
        start, end = data_proxy.available_data_range(config.strategy.frequency, config.strategy.start_date, config.strategy.end_date)
        config.strategy.start_date = max(start, config.strategy.start_date)
        config.strategy.end_date = min(end, config.strategy.end_date)
        config.strategy.trading_calendar = data_proxy.get_trading_dates(config.strategy.start_date, config.strategy.end_date)
        if len(config.strategy.trading_calendar) == 0 or int(config.strategy.trading_calendar[-1].date().strftime('%Y%m%d')) > end:
            raise ValueError(_(f'数据有效范围为({start!s}，{end!s})，请联系工作人员'))
        config.strategy.start_date = config.strategy.trading_calendar[0].date()
        config.strategy.end_date = config.strategy.trading_calendar[-1].date()
